import{_ as t,c as r,o as s,j as e,ag as p,a as i}from"./chunks/framework.DQvKz0xt.js";const m=JSON.parse('{"title":"形状与路径概览 (Shapes and Paths Overview) - Rive 编辑器","description":"在 Rive 中，形状 (Shapes) 和路径 (Paths) 由两种不同的图层类型组成：形状图层 (Shape Layers) 和 路径图层 (Path Layers)。 形状图层由蓝色图标表示，它是路径图层的容器。","frontmatter":{"title":"形状与路径概览 (Shapes and Paths Overview) - Rive 编辑器","description":"在 Rive 中，形状 (Shapes) 和路径 (Paths) 由两种不同的图层类型组成：形状图层 (Shape Layers) 和 路径图层 (Path Layers)。 形状图层由蓝色图标表示，它是路径图层的容器。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 基础概念, 形状与路径概览"}]]},"headers":[],"relativePath":"editor/fundamentals/shapes-and-paths-overview.md","filePath":"editor/fundamentals/shapes-and-paths-overview.md","lastUpdated":1774838907000}'),h={name:"editor/fundamentals/shapes-and-paths-overview.md"};function o(n,a,l,d,c,v){return s(),r("div",null,[...a[0]||(a[0]=[e("h1",{id:"形状与路径概览-shapes-and-paths-overview",tabindex:"-1"},[i("形状与路径概览 (Shapes and Paths Overview) "),e("a",{class:"header-anchor",href:"#形状与路径概览-shapes-and-paths-overview","aria-label":'Permalink to "形状与路径概览 (Shapes and Paths Overview)"'},"​")],-1),e("div",{class:"video-container"},[e("iframe",{width:"100%",height:"400",src:"https://www.youtube.com/embed/KunkCnbkTsg",title:"Rive 101 - Shapes and Paths",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),p('<p>在 Rive 中，形状 (Shapes) 和路径 (Paths) 由两种不同的图层类型组成：<strong>形状图层 (Shape Layers)</strong> 和 <strong>路径图层 (Path Layers)</strong>。</p><p><img src="https://help.rive.app/images/shape-and-path-shapelayer.png" alt="Shape Layer Overview"></p><h2 id="形状图层-shape-layer" tabindex="-1">形状图层 (Shape Layer) <a class="header-anchor" href="#形状图层-shape-layer" aria-label="Permalink to &quot;形状图层 (Shape Layer)&quot;">​</a></h2><p><img src="https://help.rive.app/images/shape-and-path-properties.png" alt="Shape Layer Icon"></p><p>形状图层由<strong>蓝色</strong>图标表示，它是路径图层的<strong>容器</strong>。</p><p>形状图层本身并不直接包含各种属性或顶点。相反，它作为容纳路径、填充 (Fills) 和描边 (Strokes) 的容器。您可以将多个路径图层放置在一个形状图层中，它们将共享同一套填充和描边样式。</p><p><img src="https://help.rive.app/images/shape-and-path-fill.png" alt="Fill and Stroke"></p><h2 id="路径图层-path-layer" tabindex="-1">路径图层 (Path Layer) <a class="header-anchor" href="#路径图层-path-layer" aria-label="Permalink to &quot;路径图层 (Path Layer)&quot;">​</a></h2><p><img src="https://help.rive.app/images/shape-and-path-pathlayer.gif" alt="Path Layer Icon"></p><p>路径图层由<strong>灰色</strong>图标表示。</p><p>这是构成矢量图形的核心部分。路径图层包含定义形状的所有顶点数据。路径图层必须始终嵌套在形状图层内部才能被渲染。</p><h3 id="路径图层属性-path-layer-properties" tabindex="-1">路径图层属性 (Path Layer Properties) <a class="header-anchor" href="#路径图层属性-path-layer-properties" aria-label="Permalink to &quot;路径图层属性 (Path Layer Properties)&quot;">​</a></h3><p>当您选中一个路径图层时，可以在属性检查器中看到一个 <strong>Closed (闭合)</strong> 选项。</p><ul><li><strong>勾选 Closed</strong>: 路径将自动连接起点和终点，形成一个封闭的图形。</li><li><strong>取消 Closed</strong>: 路径将保持开放。</li></ul><h2 id="enter-和-esc-快捷键" tabindex="-1">Enter 和 Esc 快捷键 <a class="header-anchor" href="#enter-和-esc-快捷键" aria-label="Permalink to &quot;Enter 和 Esc 快捷键&quot;">​</a></h2><p>为了加快工作流程，Rive 提供了方便的快捷键来在层级之间导航。</p><ul><li><strong>Enter</strong>: 当选中一个形状图层时，按下 <code>Enter</code> 键可以选择其内部的第一个路径图层（进入编辑模式）。这允许您快速开始编辑顶点。</li><li><strong>Esc</strong>: 当选中一个路径图层或正在编辑顶点时，按下 <code>Esc</code> 键将使选择向上移动一级，选回父级的形状图层。</li></ul><p><img src="https://help.rive.app/images/shape-and-path-move.gif" alt="Move Shortcut"></p>',18)])])}const u=t(h,[["render",o]]);export{m as __pageData,u as default};
